from typing import List, Mapping, Optional, Tuple
import heapq


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits or dst not in limits:
        raise KeyError("src or dst not in limits")
    if src == dst:
        raise ValueError("src and dst must be different")

    # pq stores (-capacity, length, path)
    # heapq is a min-heap, so it will pop:
    # 1. Smallest -capacity (highest capacity)
    # 2. Smallest length (shortest path)
    # 3. Smallest path (lexicographical order)
    pq = [(-float('inf'), 1, [src])]

    # visited[node] stores the best (-capacity, length, path) found so far
    visited = {src: (-float('inf'), 1, [src])}

    while pq:
        neg_cap, length, path = heapq.heappop(pq)
        cap = -neg_cap
        u = path[-1]

        if u == dst:
            return int(cap), path

        if (neg_cap, length, path) > visited.get(u, (float('inf'), float('inf'), [])):
            continue

        if u in limits:
            for v, limit in limits[u].items():
                new_cap = min(cap, limit)
                new_neg_cap = -new_cap
                new_len = length + 1
                new_path = path + [v]

                new_entry = (new_neg_cap, new_len, new_path)
                if v not in visited or new_entry < visited[v]:
                    visited[v] = new_entry
                    heapq.heappush(pq, new_entry)

    return None
