from typing import Dict, Iterable, List, Set, Tuple


def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find the roads whose closure would cut a region in two.

    Roads are undirected and the network is built with ``build_adjacency``. A road
    between depots ``a`` and ``b`` is critical if, once it is closed, ``b`` can no
    longer be reached from ``a``. Self-loops are never critical. Networks are small (a
    few dozen roads), so checking each road separately is fine.

    Returns the critical roads as (code_a, code_b) tuples,
    sorted.

    Example:
        critical_roads([("A", "B", 1), ("B", "C", 1), ("C", "A", 1), ("C", "D", 4)]) == [("C", "D", 4)]
    """
    edge_list = list(edges)

    adj: Dict[str, List[Tuple[str, int]]] = {}
    for i, (u, v, _) in enumerate(edge_list):
        if u == v:
            continue
        adj.setdefault(u, []).append((v, i))
        adj.setdefault(v, []).append((u, i))

    critical_indices: Set[int] = set()

    for i, (u, v, _) in enumerate(edge_list):
        if u == v:
            continue

        visited: Set[str] = {u}
        queue = [u]
        found_v = False

        idx = 0
        while idx < len(queue):
            curr = queue[idx]
            idx += 1
            if curr == v:
                found_v = True
                break

            for neighbor, edge_idx in adj.get(curr, []):
                if edge_idx != i and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        if not found_v:
            critical_indices.add(i)

    results = []
    for i in critical_indices:
        u, v, _ = edge_list[i]
        results.append(tuple(sorted((u, v))))

    return sorted(results)"}}, "messages": []}

